    def load_stock_data(self, stock: str, data: List[Dict]) -> None:
        """Load historical data for a stock."""
        self.stock_data[stock] = data
        self.ma_cache[stock] = {}

    def calculate_moving_average(self, values: List[float], period: int) -> Optional[float]:
        """Calculate simple moving average."""
        if len(values) < period:
            return None
        return sum(values[-period:]) / period

    def update_mas(self, stock: str) -> Dict[int, float]:
        """Update moving averages for a stock."""
        if stock not in self.stock_data or not self.stock_data[stock]:
            return {}

        closes = [d["close"] for d in self.stock_data[stock] if "close" in d]
        result = {}
        for period in self.ma_periods:
            ma = self.calculate_moving_average(closes, period)
            result[period] = ma
        self.ma_cache[stock] = result
        return result

    def get_latest_record(self, stock: str) -> Optional[Dict]:
        """Get the most recent data record for a stock."""
        if stock in self.stock_data and self.stock_data[stock]:
            return self.stock_data[stock][-1]
        return None

    def get_prev_record(self, stock: str) -> Optional[Dict]:
        """Get the second-to-last data record for a stock."""
        if stock in self.stock_data and len(self.stock_data[stock]) >= 2:
            return self.stock_data[stock][-2]
        return None

    def calculate_momentum_score(self, stock: str, lookback: Optional[int] = None) -> Optional[float]:
        """Calculate momentum score (return over lookback period)."""
        if lookback is None:
            lookback = self.momentum_lookback

        if stock not in self.stock_data:
            return None

        data = self.stock_data[stock]
        if len(data) < lookback + 1:
            return None

        current_close = data[-1]["close"]
        old_close = data[-1 - lookback]["close"]

        if old_close == 0:
            return None

        return (current_close - old_close) / old_close
ENDOFPART7
